prompt.text:
/* 色名一覧の作成 */
for (i を 1 から colorsの要素数 まで)
    if (colorVectorのいずれにも colors[i]がない)
        colorVectorの末尾に a を追加
    endif
endfor

/* One-Hot表現への変換 */
for (j を 1 から colorsの要素数 まで)
    tempVector ← {}
    for (k を 1 から colorVectorの要素数 まで)
        if (b)
            tempVectorの末尾に 1 を追加
        else
            tempVectorの末尾に 0 を追加
        endif
    endfor
    oneHotVectorの末尾に tempVectorを追加
endfor
